--- a/gas/config/tc-mips.c
+++ b/gas/config/tc-mips.c
@@ -1624,7 +1624,6 @@
 	  fragS *old_frag;
 	  unsigned long old_frag_offset;
 	  int i;
-	  struct insn_label_list *l;

 	  old_frag = frag_now;
 	  old_frag_offset = frag_now_fix ();
@@ -1646,15 +1645,9 @@
 	      frag_grow (40);
 	    }

-	  for (l = insn_labels; l != NULL; l = l->next)
-	    {
-	      assert (S_GET_SEGMENT (l->label) == now_seg);
-	      l->label->sy_frag = frag_now;
-	      S_SET_VALUE (l->label, (valueT) frag_now_fix ());
-	      /* mips16 text labels are stored as odd.  */
-	      if (mips_opts.mips16)
-		++l->label->sy_value.X_add_number;
-	    }
+	  /* Leave any pending labels before the hazard nops (the
+	     original SCE assembler did not move them after the nops;
+	     mips_emit_delays still does).  */

 #ifndef NO_ECOFF_DEBUGGING
 	  if (ECOFF_DEBUGGING)
@@ -4144,6 +4137,25 @@
 	  offset_expr.X_op = O_constant;
 	}

+      /* A base register plus a 16-bit immediate offset is a single
+	 addiu (daddiu for dla or 64-bit addresses), as GNU as
+	 2.10-ee-001003-1 assembles it; backported from upstream
+	 binutils 0c11417f (2002-08-09).  Every other case keeps the
+	 expansion below.  */
+      if (offset_expr.X_op == O_constant
+	  && breg != 0
+	  && offset_expr.X_add_number >= -0x8000
+	  && offset_expr.X_add_number < 0x8000)
+	{
+	  macro_build ((char *) NULL, &icnt, &offset_expr,
+		       ((dbl
+			 || ! (bfd_arch_bits_per_address (stdoutput) == 32
+			       || mips_opts.isa < 3))
+			? "daddiu" : "addiu"),
+		       "t,r,j", treg, breg, (int) BFD_RELOC_LO16);
+	  return;
+	}
+
       if (treg == breg)
 	{
 	  tempreg = AT;
@@ -11699,7 +11711,8 @@
       fixptr = fragp->fr_literal + fragp->fr_fix;

       if (new > 0)
-	memcpy (fixptr - old, fixptr, new);
+	/* Expanded alternatives can overlap their final destination.  */
+	memmove (fixptr - old, fixptr, new);

       fragp->fr_fix += new - old;
     }
--- a/opcodes/mips-opc.c
+++ b/opcodes/mips-opc.c
@@ -242,7 +242,7 @@
 {"vrxor", "X,8",	0x4a00043f, 0xff9f07ff,	0, 		T5},
 {"vsqd",  "&2K,(--4)K",	0x4a00037f, 0xfe0007ff,	0, 		T5},
 {"vsqi",  "&2K,(4++)K",	0x4a00037d, 0xfe0007ff,	0, 		T5},
-{"vsqrt", "Q,7",	0x4a0003bd, 0xfe60ffff,	0, 		T5},
+{"vsqrt", "Q,7",	0x4a2003bd, 0xfe60ffff,	0, 		T5}, /* masked bits 21-22 are 01 */
 {"vsub",  "&3K,2K,1K",	0x4a00002c, 0xfe00003f,	0, 		T5},
 {"vsubi", "&3K,2K,J",	0x4a000026, 0xfe1f003f,	0, 		T5},
 {"vsubq", "&3K,2K,Q",	0x4a000024, 0xfe1f003f,	0, 		T5},
